import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadMysoreData(){const e=readFileSync(resolve(__dirname,"../../mysore-coinage-explorer/mysore-coin-data.js"),"utf-8");return new Function(e+"\nreturn { MYSORE_INFO, COIN_DENOMINATIONS, MAULUDI_CALENDAR_INFO, MINTS_LIST, TIMELINE_EVENTS, REFERENCES };")()}describe("Mysore Coinage Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadMysoreData()}),describe("MYSORE_INFO metadata",()=>{it("contains correct Mysore coinage metadata and Tipu Sultan reforms",()=>{expect(e.MYSORE_INFO.id).toBe("mysore-coinage"),expect(e.MYSORE_INFO.title).toContain("Mysore"),expect(e.MYSORE_INFO.keyInnovator).toContain("Tipu Sultan"),expect(e.MYSORE_INFO.calendarSystem).toContain("Mauludi")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.MYSORE_INFO.quickStats)).toBe(!0),expect(e.MYSORE_INFO.quickStats.length).toBe(6)})}),describe("COIN_DENOMINATIONS & MINTS_LIST",()=>{it("contains celestial named coins and imperial mints",()=>{expect(Array.isArray(e.COIN_DENOMINATIONS)).toBe(!0),expect(e.COIN_DENOMINATIONS.length).toBeGreaterThanOrEqual(4);const t=e.COIN_DENOMINATIONS.find(e=>"ahmadi-mohur"===e.id);expect(t).toBeDefined(),expect(t.metal).toContain("Gold"),expect(Array.isArray(e.MINTS_LIST)).toBe(!0),expect(e.MINTS_LIST.length).toBeGreaterThanOrEqual(4)})}),describe("TIMELINE_EVENTS & REFERENCES",()=>{it("contains historical timeline and references",()=>{expect(Array.isArray(e.TIMELINE_EVENTS)).toBe(!0),expect(e.TIMELINE_EVENTS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});